INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,catalogue_number,short_quote,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(id,7),id,
 CASE
  WHEN id IN ('claim.v0100.tamayori_parent_kamo','claim.v0100.taketsunumi_parent_tamayori','claim.v0100.hono_parent_kamo','claim.v0100.kamo_associated_raijin','claim.v0100.kamo_associated_thunder') THEN 'source.japanese.kamo_genealogy.kokugakuin'
  WHEN id='claim.v0100.kamo_worshipped_kamigamo' THEN 'source.japanese.kamigamo.about'
  WHEN id IN ('claim.v0100.festival_deity','claim.v0100.festival_site') THEN 'source.japanese.kamo_festival.official'
  WHEN id IN ('claim.v0100.kurabeuma_deity','claim.v0100.kurabeuma_site','claim.v0100.kurabeuma_festival') THEN 'source.japanese.kamo_kurabeuma.official'
  WHEN id='claim.v0100.kamigamo_unesco' THEN 'source.japanese.kamigamo.unesco688'
  ELSE 'source.japanese.raijin_screen.kyohaku' END,
 CASE
  WHEN id LIKE 'claim.v0100.%parent%' OR id='claim.v0100.hono_parent_kamo' THEN 'Fragmentary Yamashiro no kuni fudoki genealogy discussion'
  WHEN id LIKE 'claim.v0100.festival_%' THEN 'Kamo Festival public description'
  WHEN id LIKE 'claim.v0100.kurabeuma_%' THEN 'Kamo Kurabeuma public description'
  WHEN id='claim.v0100.kamigamo_unesco' THEN 'World Heritage component map'
  ELSE 'Official catalogue or public institutional description' END,
 CASE WHEN id='claim.v0100.kamigamo_unesco' THEN 'World Heritage 688-001' WHEN id LIKE 'claim.v0100.screen_%' OR id='claim.v0100.raijin_screen' THEN 'National Treasure; Kennin-ji pair' ELSE NULL END,
 NULL,
 CASE WHEN id LIKE 'claim.v0100.screen_%' OR id='claim.v0100.raijin_screen' THEN 'MUSEUM_OBJECT' WHEN id='claim.v0100.kamigamo_unesco' THEN 'OFFICIAL_SITE' WHEN id LIKE 'claim.v0100.%parent%' OR id='claim.v0100.hono_parent_kamo' THEN 'MODERN_SCHOLARSHIP' ELSE 'OFFICIAL_SITE' END,
 'SUPPORTS',confidence,
 'Independent summary only; locator and evidence scope retained.'
FROM claims WHERE id LIKE 'claim.v0100.%';

